class InlineKeyboardButton:
    def __init__(self, data: dict):
        self.data = data

    @staticmethod
    def create(text: str,
               url: str = None,
               callback_data: str = None,
               switch_inline_query: str = None,
               switch_inline_query_current_chat: str = None,
               pay: bool = None):
        data = {}
        data.setdefault("text", text)
        data.setdefault("url", url)
        data.setdefault("callback_data", callback_data)
        data.setdefault("switch_inline_query", switch_inline_query)
        data.setdefault("switch_inline_query_current_chat", switch_inline_query_current_chat)
        data.setdefault("pay", pay)
        return InlineKeyboardButton(data)

    @staticmethod
    def switch_inline_query(text: str, query: str = "", current_chat: bool = True):
        switch_inline_query_key = "switch_inline_query_current_chat" if current_chat else "switch_inline_query"
        return InlineKeyboardButton({
            "text": text,
            switch_inline_query_key: query
        })

